class Solution:
 def findLucky(self,arr):
  c=Counter(arr);return max((x for x,n in c.items() if x==n),default=-1)

class Solution:
 def minSubsequence(self,nums):
  nums.sort(reverse=True);total=sum(nums);cur=0;out=[]
  for x in nums:
   out.append(x);cur+=x
   if cur>total-cur:break
  return out

class Solution:
 def kidsWithCandies(self,candies,extraCandies):
  m=max(candies);return [x+extraCandies>=m for x in candies]

class Solution:
 def destCity(self,paths):
  starts={a for a,b in paths}
  return next(b for a,b in paths if b not in starts)

class Solution:
 def buildArray(self,target,n):
  wanted=set(target);out=[]
  for x in range(1,target[-1]+1):
   out.append('Push')
   if x not in wanted:out.append('Pop')
  return out

from collections import Counter
class Solution:
 def canBeEqual(self,target,arr):return Counter(target)==Counter(arr)

class Solution:
 def shuffle(self,nums,n):
  out=[]
  for i in range(n):out.extend([nums[i],nums[i+n]])
  return out

class Solution:
 def finalPrices(self,prices):
  out=prices.copy();stack=[]
  for i,p in enumerate(prices):
   while stack and prices[stack[-1]]>=p:out[stack.pop()]-=p
   stack.append(i)
  return out

class Solution:
 def runningSum(self,nums):
  total=0;out=[]
  for x in nums:total+=x;out.append(total)
  return out
